gridProps.items:
{source.vocabulary.map((item) => ({
          id: item.audioId,
          word: item.word,
          translation: item.translation,
          example: item.example,
          initialHint: item.initialHint,
          imageUrl: atlas,
          imageRegion: item.imageRegion,
          imageAlt: `A learning situation showing ${item.word}`,
        }))}

gridProps.controls:
{{
          showInitial: initial,
          showAll: all,
          onToggleInitial: () => setInitial((value) => !value),
          onToggleAll: () => setAll((value) => !value),
        }}

gridProps.onPlay:
{(id) => {
          const item = source.vocabulary.find((word) => word.audioId === id)
          if (item)
            speech.speak([{ id: item.classAudioId, text: item.classAudioText }])
        }}

gridProps.items:
{source.vocabulary.map((item, index) => ({
          ...item,
          imageUrl: atlas,
          imageRegion: {
            columns: 3,
            rows: 2,
            column: index % 3,
            row: Math.floor(index / 3),
            sourceAspectRatio: 3 / 2,
          },
          imageAlt: `Interview scene representing ${item.word}`,
        }))}

gridProps.controls:
{{
          showAll: all,
          showInitial: hints,
          onToggleAll: () => showAll(!all),
          onToggleInitial: () => showHints(!hints),
        }}
